WITH raw(source_record_id,scope_key,technical_code,timestamp,actor,object_refs,source_table) AS (SELECT record_key source_record_id, document_ref scope_key, state_code technical_code, created_day||'T'||created_clock||'Z' timestamp, operator_code actor, related_refs_json object_refs, 'commercial_document' source_table FROM commercial_document UNION ALL SELECT record_key, job_ref, phase_code, effective_at, operator_code, related_refs_json, 'engineering_execution' FROM engineering_execution UNION ALL SELECT record_key, supply_ref, movement_code, substr(posting_day,1,4)||'-'||substr(posting_day,5,2)||'-'||substr(posting_day,7,2)||'T'||printf('%02d:%02d:%02d',posting_seconds/3600,(posting_seconds/60)%60,posting_seconds%60)||'Z', operator_code, related_refs_json, 'supply_posting' FROM supply_posting UNION ALL SELECT record_key, inspection_ref, result_code, strftime('%Y-%m-%dT%H:%M:%SZ',observed_epoch_ms/1000,'unixepoch'), operator_code, related_refs_json, 'quality_observation' FROM quality_observation UNION ALL SELECT record_key, fulfilment_ref, milestone_code, strftime('%Y-%m-%dT%H:%M:%SZ',milestone_epoch,'unixepoch'), operator_code, related_refs_json, 'fulfilment_record' FROM fulfilment_record UNION ALL SELECT record_key, posting_ref, posting_code, substr(effective_day,1,10)||'T'||substr(effective_clock,1,2)||':'||substr(effective_clock,3,2)||':'||substr(effective_clock,5,2)||'Z', operator_code, related_refs_json, 'finance_posting' FROM finance_posting), mapped AS (SELECT *, CASE technical_code WHEN 'FF001' THEN 'RFQ Created' WHEN 'FF002' THEN 'RFQ Line Added' WHEN 'FF003' THEN 'Quote Prepared' WHEN 'FF004' THEN 'Quote Revised' WHEN 'FF005' THEN 'Quote Approved' WHEN 'FF006' THEN 'Quote Sent' WHEN 'FF007' THEN 'Quote Accepted' WHEN 'FF008' THEN 'Sales Order Created' WHEN 'FF009' THEN 'Order Line Added' WHEN 'FF010' THEN 'Configuration Frozen' WHEN 'FF011' THEN 'Credit Check Failed' WHEN 'FF012' THEN 'Credit Check Passed' WHEN 'FF013' THEN 'Order Released' WHEN 'FF014' THEN 'Engineering Change Requested' WHEN 'FF015' THEN 'Engineering Change Approved' WHEN 'FF016' THEN 'Engineering Change Implemented' WHEN 'FF017' THEN 'BOM Revision Released' WHEN 'FF018' THEN 'Work Order Created' WHEN 'FF019' THEN 'Work Order Released' WHEN 'FF020' THEN 'Material Reserved' WHEN 'FF021' THEN 'Material Shortage Detected' WHEN 'FF022' THEN 'Purchase Requisition Created' WHEN 'FF023' THEN 'Purchase Order Issued' WHEN 'FF024' THEN 'Supplier Confirmation Received' WHEN 'FF025' THEN 'Goods Receipt Posted' WHEN 'FF026' THEN 'Incoming Inspection Started' WHEN 'FF027' THEN 'Incoming Inspection Passed' WHEN 'FF028' THEN 'Incoming Inspection Failed' WHEN 'FF029' THEN 'Material Issued to Work Order' WHEN 'FF030' THEN 'Operation Started' WHEN 'FF031' THEN 'Operation Completed' WHEN 'FF032' THEN 'Production Paused' WHEN 'FF033' THEN 'Production Resumed' WHEN 'FF034' THEN 'Nonconformance Raised' WHEN 'FF035' THEN 'Rework Ordered' WHEN 'FF036' THEN 'Rework Completed' WHEN 'FF037' THEN 'Final Inspection Passed' WHEN 'FF038' THEN 'Final Inspection Failed' WHEN 'FF039' THEN 'Serial Number Assigned' WHEN 'FF040' THEN 'Finished Goods Received' WHEN 'FF041' THEN 'Shipment Planned' WHEN 'FF042' THEN 'Package Sealed' WHEN 'FF043' THEN 'Shipment Dispatched' WHEN 'FF044' THEN 'Delivery Confirmed' WHEN 'FF045' THEN 'Invoice Issued' WHEN 'FF046' THEN 'Payment Received' WHEN 'FF047' THEN 'Warranty Registered' WHEN 'FF048' THEN 'Order Closed' END activity FROM raw) SELECT dc.predecessor_key case_id, activity, timestamp, source_table, source_record_id, actor, object_refs FROM mapped JOIN document_conversion dc ON dc.successor_key=mapped.scope_key WHERE activity IS NOT NULL ORDER BY timestamp, source_record_id;
